CREATE TYPE "lifecycle_stage" AS ENUM ('lead', 'qualified', 'checkout_started', 'customer', 'at_risk', 'churned');
CREATE TYPE "lifecycle_event_type" AS ENUM ('lead', 'checkout_started', 'payment_pending', 'payment_expired', 'paid', 'refunded', 'activation', 'renewal', 'message_opened', 'message_clicked');
CREATE TYPE "lifecycle_event_status" AS ENUM ('accepted', 'processed', 'failed');
CREATE TYPE "lifecycle_action_status" AS ENUM ('pending', 'claimed', 'completed', 'failed', 'suppressed');
CREATE TABLE "lifecycle_contacts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "email" text, "phone" text, "name" text, "email_consent" boolean NOT NULL DEFAULT false, "whatsapp_consent" boolean NOT NULL DEFAULT false, "stage" "lifecycle_stage" NOT NULL DEFAULT 'lead', "temperature" integer NOT NULL DEFAULT 0, "purchase_probability" integer NOT NULL DEFAULT 0, "lifetime_value_cents" integer NOT NULL DEFAULT 0, "churn_risk" integer NOT NULL DEFAULT 0, "source" text, "profile" jsonb NOT NULL DEFAULT '{}'::jsonb, "last_activity_at" timestamp with time zone, "created_at" timestamp with time zone NOT NULL DEFAULT now(), "updated_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "lifecycle_contacts_workspace_email_unique" ON "lifecycle_contacts" ("workspace_id","email");
CREATE UNIQUE INDEX "lifecycle_contacts_workspace_phone_unique" ON "lifecycle_contacts" ("workspace_id","phone");
CREATE TABLE "lifecycle_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "contact_id" uuid REFERENCES "lifecycle_contacts"("id") ON DELETE set null, "event_key" text NOT NULL, "type" "lifecycle_event_type" NOT NULL, "status" "lifecycle_event_status" NOT NULL DEFAULT 'accepted', "subject_type" text, "subject_id" text, "payload" jsonb NOT NULL DEFAULT '{}'::jsonb, "occurred_at" timestamp with time zone NOT NULL, "processed_at" timestamp with time zone, "created_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "lifecycle_events_workspace_key_unique" ON "lifecycle_events" ("workspace_id","event_key");
CREATE TABLE "cart_recovery_actions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "sale_id" uuid NOT NULL REFERENCES "product_sales"("id") ON DELETE cascade, "contact_id" uuid REFERENCES "lifecycle_contacts"("id") ON DELETE set null, "status" "lifecycle_action_status" NOT NULL DEFAULT 'pending', "channel" text NOT NULL, "provider_dispatch_id" uuid, "reason" text, "attempted_at" timestamp with time zone, "completed_at" timestamp with time zone, "created_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "cart_recovery_sale_channel_unique" ON "cart_recovery_actions" ("sale_id","channel");
CREATE TABLE "buyer_onboarding_instances" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "sale_id" uuid NOT NULL REFERENCES "product_sales"("id") ON DELETE cascade, "contact_id" uuid REFERENCES "lifecycle_contacts"("id") ON DELETE set null, "product_id" uuid NOT NULL REFERENCES "products"("id"), "status" "lifecycle_action_status" NOT NULL DEFAULT 'pending', "activated_at" timestamp with time zone, "created_at" timestamp with time zone NOT NULL DEFAULT now(), "updated_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "buyer_onboarding_sale_unique" ON "buyer_onboarding_instances" ("sale_id");
CREATE TYPE "referral_reward_status" AS ENUM ('pending', 'earned', 'fulfilled', 'reversed', 'rejected');
CREATE TABLE "retention_actions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "contact_id" uuid NOT NULL REFERENCES "lifecycle_contacts"("id") ON DELETE cascade, "status" "lifecycle_action_status" NOT NULL DEFAULT 'pending', "risk_score" integer NOT NULL, "reason" text NOT NULL, "provider_dispatch_id" uuid, "created_at" timestamp with time zone NOT NULL DEFAULT now(), "completed_at" timestamp with time zone);
CREATE UNIQUE INDEX "retention_contact_reason_unique" ON "retention_actions" ("contact_id","reason");
CREATE TABLE "upsell_offers" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "product_id" uuid NOT NULL REFERENCES "products"("id") ON DELETE cascade, "target_product_id" uuid NOT NULL REFERENCES "products"("id") ON DELETE cascade, "approved" boolean NOT NULL DEFAULT false, "minimum_activation_hours" integer NOT NULL DEFAULT 0, "created_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE "upsell_actions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "offer_id" uuid NOT NULL REFERENCES "upsell_offers"("id") ON DELETE cascade, "contact_id" uuid NOT NULL REFERENCES "lifecycle_contacts"("id") ON DELETE cascade, "source_sale_id" uuid NOT NULL REFERENCES "product_sales"("id") ON DELETE cascade, "converted_sale_id" uuid REFERENCES "product_sales"("id") ON DELETE set null, "status" "lifecycle_action_status" NOT NULL DEFAULT 'pending', "created_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "upsell_action_offer_source_sale_unique" ON "upsell_actions" ("offer_id","source_sale_id");
CREATE TABLE "purchaser_referrals" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "referrer_contact_id" uuid NOT NULL REFERENCES "lifecycle_contacts"("id") ON DELETE cascade, "code" text NOT NULL, "active" boolean NOT NULL DEFAULT true, "expires_at" timestamp with time zone, "created_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "purchaser_referrals_workspace_code_unique" ON "purchaser_referrals" ("workspace_id","code"); CREATE UNIQUE INDEX "purchaser_referrals_referrer_unique" ON "purchaser_referrals" ("referrer_contact_id");
CREATE TABLE "purchaser_referral_attributions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "referral_id" uuid NOT NULL REFERENCES "purchaser_referrals"("id") ON DELETE cascade, "referred_contact_id" uuid NOT NULL REFERENCES "lifecycle_contacts"("id") ON DELETE cascade, "sale_id" uuid NOT NULL REFERENCES "product_sales"("id") ON DELETE cascade, "created_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "purchaser_referral_attribution_sale_unique" ON "purchaser_referral_attributions" ("sale_id");
CREATE TABLE "referral_rewards" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE cascade, "attribution_id" uuid NOT NULL REFERENCES "purchaser_referral_attributions"("id") ON DELETE cascade, "status" "referral_reward_status" NOT NULL DEFAULT 'pending', "amount_cents" integer NOT NULL DEFAULT 0, "reason" text NOT NULL, "created_at" timestamp with time zone NOT NULL DEFAULT now(), "reversed_at" timestamp with time zone);
CREATE UNIQUE INDEX "referral_reward_attribution_unique" ON "referral_rewards" ("attribution_id");